const D = { density:.5, warp:.25, energy:.6, speed:1, scale:1, hue:210, x:.5, y:.5, style:'stained', pal:'spectrum', act:'drift', seed:0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const md=(a,n)=>((a%n)+n)%n, clp=(v,a,b)=>Math.max(a,Math.min(b,v)), TAU=Math.PI*2;
const fr=i=>{const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453;return s-Math.floor(s);};
if(S.lastBeat==null||K.beat<S.lastBeat)S.lastBeat=K.beat; S.lastBeat=K.beat;

const W=width,Hh=height,u=Math.min(W,Hh);
const style=P.style, pal=P.pal;
const dens=clp(P.density,0,1), warp=clp(P.warp,0,1), en=clp(P.energy,0,1)*(.45+.7*K.intensity);
const NS=Math.max(4,Math.round(6+dens*54));                 // 6..60 sites
const gN=Math.max(14,Math.round(16+ (1-clp(P.scale,0.4,2.2)/2.2)*22 )); // coarseness by scale (bigger scale -> chunkier)

// ---- seed-deterministic site field (normalized coords) ----
if(S.seedUsed!==P.seed || !S.sx || S.nUsed!==NS){
  S.seedUsed=P.seed; S.nUsed=NS;
  S.sx=[]; S.sy=[]; S.vx=[]; S.vy=[]; S.sh=[]; S.sk=[];
  for(let i=0;i<NS;i++){
    S.sx[i]=fr(i*1.3+3.1); S.sy[i]=fr(i*2.7+7.7);
    const ang=fr(i*5.1)*TAU, sp=0.02+0.05*fr(i*9.2);
    S.vx[i]=Math.cos(ang)*sp; S.vy[i]=Math.sin(ang)*sp;
    S.sh[i]=fr(i*3.9); S.sk[i]=fr(i*11.3);               // hue jitter, warp phase
  }
  S.lastT=null;
}
// integrate drift by real seconds (never re-phases; tolerate t0 reset)
if(S.lastT==null || K.t<S.lastT) S.lastT=K.t;
let dt=clp(K.t-S.lastT,0,0.05); S.lastT=K.t;
const rate=(0.25+0.9*en)*clp(P.speed,0.2,4);
// act dramaturgy: drift=free, swarm=gather-then-scatter each section, breathe=in/out pulse
let radial=(K.pulse*0.12+A.bass*0.20)*en;                 // +out on the beat
if(P.act==='swarm'){ radial += (K.section%2? 0.09 : -0.09)*en; }        // alternate gather/scatter
else if(P.act==='breathe'){ radial += Math.sin(K.t*0.12)*0.10*en; }     // slow inhale/exhale
for(let i=0;i<NS;i++){
  S.sx[i]+=S.vx[i]*dt*rate + (S.sx[i]-P.x)*radial*dt*3;
  S.sy[i]+=S.vy[i]*dt*rate + (S.sy[i]-P.y)*radial*dt*3;
  if(S.sx[i]<0.02){S.sx[i]=0.02;S.vx[i]=Math.abs(S.vx[i]);} else if(S.sx[i]>0.98){S.sx[i]=0.98;S.vx[i]=-Math.abs(S.vx[i]);}
  if(S.sy[i]<0.02){S.sy[i]=0.02;S.vy[i]=Math.abs(S.vy[i]);} else if(S.sy[i]>0.98){S.sy[i]=0.98;S.vy[i]=-Math.abs(S.vy[i]);}
}
// warp wander of boundaries (per-site slow offset, real-time)
const wa=warp*0.06;
const px=[],py=[];
for(let i=0;i<NS;i++){
  px[i]=(S.sx[i]+wa*Math.sin(K.t*(0.3+S.sk[i]*0.6)+S.sk[i]*TAU))*W;
  py[i]=(S.sy[i]+wa*Math.cos(K.t*(0.25+S.sh[i]*0.5)+S.sh[i]*TAU))*Hh;
}

// ---- palette ----
function cellHue(i){
  const base=md(P.hue + (pal==='spectrum'? S.sh[i]*300 : pal==='duo'? (i%2)*160 : pal==='warm'? S.sh[i]*70 : pal==='cool'? 140+S.sh[i]*120 : S.sh[i]*40),360);
  return base;
}
const dark = style==='contour'||style==='thermal'||pal==='mono';
// background base
if(style==='contour'){ background(md(P.hue+200,360),40,7); }
else if(style==='thermal'){ background(255,60,4); }
else if(pal==='mono'){ background(md(P.hue,360),8,10); }
else { background(md(P.hue+180,360),20,8); }

const cw=W/gN, ch=Hh/gN;
noStroke();
// section drives global saturation/brightness breathing
const secB=0.85+0.3*Math.sin(K.t*0.05+K.section);
const glow=(0.3+0.7*en)*(0.6+0.6*K.swell+0.8*A.treble);

for(let gx=0;gx<gN;gx++){
  const cx=gx*cw+cw*0.5;
  for(let gy=0;gy<gN;gy++){
    const cy=gy*ch+ch*0.5;
    let best=1e18,b2=1e18,bi=0;
    for(let k=0;k<NS;k++){
      const dx=px[k]-cx, dy=py[k]-cy, d=dx*dx+dy*dy;
      if(d<best){b2=best;best=d;bi=k;} else if(d<b2){b2=d;}
    }
    const edge=clp((Math.sqrt(b2)-Math.sqrt(best))/(u*0.10),0,1); // 0 near boundary, 1 deep interior
    const h=cellHue(bi);
    if(style==='contour'){
      if(edge<0.14){ const g2=clp((0.14-edge)/0.14,0,1); fill(h,55,25+70*g2*(0.5+glow*0.5),100); rect(gx*cw,gy*ch,cw+1,ch+1); }
      continue;
    }
    if(style==='thermal'){
      // false-color heat ramp from interior(hot) to edge(cold)
      const v=clp(best/(u*u*0.10),0,1);           // normalized dist to site
      const hv=md(20 - v*230 + P.hue-210,360);    // red->blue ramp
      const b=clp(90-v*55+ (1-edge)*20*glow,10,100);
      fill(hv, 80, b, 100); rect(gx*cw,gy*ch,cw+1,ch+1); continue;
    }
    if(style==='shard'){
      const b=clp((26+58*edge)*secB,8,96);
      fill(h,70, b,100); rect(gx*cw,gy*ch,cw+1,ch+1);
      if(edge<0.05){ fill(0,0,4,100); rect(gx*cw,gy*ch,cw+1,ch+1); }  // thin hard facet break
      continue;
    }
    if(style==='membrane'){
      // organic: bright rim near boundary, translucent nucleus dark center
      const b=clp((24+50*(1-edge))*secB,8,92);
      const s2=clp(38+40*edge,20,90);
      fill(h,s2,b,100); rect(gx*cw,gy*ch,cw+1,ch+1);
      if(edge<0.10){ fill(md(h+20,360),30,96,60*glow); rect(gx*cw,gy*ch,cw+1,ch+1); }
      continue;
    }
    // stained (default): luminous glass fill + dark leading at boundaries
    const b=clp((34+52*edge)*secB,10,96);
    fill(h,62, b,100); rect(gx*cw,gy*ch,cw+1,ch+1);
    if(edge<0.06){ fill(md(P.hue+200,360),50,4,100); rect(gx*cw,gy*ch,cw+1,ch+1); } // leading
    else if(edge<0.16){ fill(h,20,96,45*glow); rect(gx*cw,gy*ch,cw+1,ch+1); }        // rim highlight
  }
}

// audio/beat sparkle at site nuclei (real-time-independent accent on top)
if(style!=='contour'){
  noStroke();
  for(let i=0;i<NS;i++){
    const r=u*0.008*(1+2*K.pulse+3*A.treble)*clp(P.scale,0.4,2.2);
    fill(md(cellHue(i)+40,360),20,100, 40+50*glow);
    circle(px[i],py[i], r);
  }
}
blendMode(BLEND); drawingContext.shadowBlur=0; noStroke();
